### `publish.go` staging + git call sites (lines 91–148)

`Publish` stages exactly one path, derived from the plan:

```go
func Publish(ctx context.Context, opts PublishOptions) (string, error) {
	opts.applyDefaults()

	repo := opts.Repository
	plan := opts.Plan
	rel := plan.RelKustomizationPath(repo.Root)

	// Stage only the file the plan changed. A blanket `git add -A` in a shared
	// checkout would sweep up anything else that happened to be there.
	if err := repo.Git.Add(ctx, rel); err != nil {
		return "", err
	}
	if err := repo.Git.Commit(ctx, commitSubject(plan), commitTrailers(plan, opts.CliVersion)); err != nil {
		return "", err
	}

	refspec := "HEAD:" + repo.Branch
	remoteRef := gitops.RemoteName + "/" + repo.Branch

	for attempt := 1; ; attempt++ {
		err := repo.Git.Push(ctx, gitops.RemoteName, refspec)
		if err == nil {
			return repo.Git.HEAD(ctx)
		}

		var rejected *git.PushRejectedError
		if !errors.As(err, &rejected) {
			// Authentication, network, a missing remote: retrying cannot help.
			return "", err
		}
		if attempt >= opts.MaxAttempts {
			return "", fmt.Errorf("gave up after %d push attempt%s: %s is being deployed to concurrently — try again",
				opts.MaxAttempts, plural(opts.MaxAttempts), repo.Branch)
		}

		fmt.Fprintf(opts.Stderr, "push rejected; rebasing onto %s and retrying (%d/%d)\n", remoteRef, attempt+1, opts.MaxAttempts)
		opts.Sleep(opts.Backoff(attempt))

		if err := repo.Git.Fetch(ctx, gitops.RemoteName, repo.Branch); err != nil {
			return "", err
		}
		if err := repo.Git.Rebase(ctx, remoteRef); err != nil {
			var conflict *git.RebaseConflictError
			if !errors.As(err, &conflict) {
				return "", err
			}
			if abortErr := repo.Git.RebaseAbort(ctx); abortErr != nil {
				return "", fmt.Errorf("%w (and the rebase could not be aborted: %v)", err, abortErr)
			}
			return "", fmt.Errorf("another deployment of %s to %s landed at the same moment, and the two changes conflict.\nNothing was pushed. Re-run to deploy on top of theirs",
				plan.Coordinate, plan.Environment)
		}
	}
}
```

The staged path comes from `internal/deploy/plan.go:307` — note the silent absolute-path fallback:

```go
func (p *Plan) RelKustomizationPath(root string) string {
	rel, err := filepath.Rel(root, p.KustomizationPath)
	if err != nil {
		return p.KustomizationPath
	}
	return filepath.ToSlash(rel)
}
```

`filepath.Rel` succeeds for a path outside `root` too (returning `../…`), so a `KustomizationPath` outside the checkout yields a `../…` relative path handed straight to `git add --`. There is no `strings.HasPrefix("..")` / `filepath.IsLocal` check.

Commit ordering detail: `Add` + `Commit` happen **once, before** the retry loop; the rebase replays that commit. There is no cleanup of the local commit if the loop gives up (the shared checkout is reset on next `gitops.Open` via `ResetHard` + `Clean`, `internal/gitops/repository.go:132–135`).

### `init.go` staging + git call sites (lines 835–903)

```go
type publishScaffoldOptions struct {
	StagingDir string
	Actions    []FileAction
	Rels       []string
	Branch     string
	Facts      initFacts
}

type publishedScaffold struct {
	Revision string
	Placeholders []Placeholder
}

func publishScaffold(ctx context.Context, opts InitOptions, repo *gitops.Repository, p publishScaffoldOptions) (publishedScaffold, error) {
	start := gitops.RemoteName + "/" + repo.Branch
	if err := repo.Git.CreateBranch(ctx, p.Branch, start); err != nil {
		return publishedScaffold{}, err
	}
	// Unconditionally, on success and on failure alike: ...
	defer func() {
		if err := repo.Git.Switch(ctx, repo.Branch); err != nil {
			fmt.Fprintf(opts.Stderr, "warning: could not restore %s in the cached checkout: %v\n", repo.Branch, err)
		}
	}()

	written, err := applyStaged(p.StagingDir, repo.Root, p.Actions)
	if err != nil {
		return publishedScaffold{}, err
	}
	// Only the paths staged, never `add -A`: the checkout is shared, and a
	// concurrent run's debris is not ours to commit.
	if err := repo.Git.Add(ctx, written...); err != nil {
		return publishedScaffold{}, err
	}
	if err := repo.Git.Commit(ctx, scaffoldSubject(p.Facts, len(written)), scaffoldTrailers(p.Facts, opts.CliVersion)); err != nil {
		return publishedScaffold{}, err
	}
	if err := repo.Git.Push(ctx, gitops.RemoteName, "HEAD:refs/heads/"+p.Branch); err != nil {
		return publishedScaffold{}, fmt.Errorf("push %s: %w\n\nA rejection here usually means the branch already exists on the remote. Delete it, or merge the open review first.", p.Branch, err)
	}

	revision, err := repo.Git.HEAD(ctx)
	if err != nil {
		return publishedScaffold{}, err
	}
	// While the branch is still current — the deferred switch above takes these
	// files back out of the working tree.
	placeholders, err := scanPlaceholders(repo.Root, p.Rels)
	if err != nil {
		return publishedScaffold{}, err
	}
	return publishedScaffold{Revision: revision, Placeholders: placeholders}, nil
}
```

Notes:
- `written` (from `applyStaged`) is the exact `git add` argument list — repo-relative, slash-separated `Rel` values.
