1	package deploy
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"math/rand/v2"
9		"os"
10		"strings"
11		"time"
12	
13		"github.com/integrio-intropy/intropy-cli/internal/git"
14		"github.com/integrio-intropy/intropy-cli/internal/gitops"
15	)
16	
17	// Trailer keys written into the deployment commit. They are a format, not just
18	// a message: `deploy history` reads them back, so treat renames as breaking.
19	const (
20		TrailerComponent   = "Deploy-Component"
21		TrailerDomain      = "Deploy-Domain"
22		TrailerSystem      = "Deploy-System"
23		TrailerEnvironment = "Deploy-Env"
24	
25		// TrailerRelease is present only when the deployment came from a published
26		// release, so `deploy history` can answer "which version is in staging"
27		// from one trailer.
28		TrailerRelease = "Deploy-Release"
29	
30		// TrailerPromotedFrom names the environment the digests were copied from,
31		// present only for a promotion. It is what distinguishes a promotion from a
32		// deployment in the log: both edit the same file the same way, and the
33		// subject alone cannot say which resolved its digests and which copied them.
34		TrailerPromotedFrom = "Deploy-Promoted-From"
35	
36		TrailerImage        = "Deploy-Image"
37		TrailerDigest       = "Deploy-Digest"
38		TrailerSourceCommit = "Deploy-Source-Commit"
39		TrailerBy           = "Deploy-By"
40		TrailerCli          = "Deploy-Cli"
41	)
42	
43	// maxPushAttempts bounds the rebase-and-retry loop. A one-line change to one
44	// file replays cleanly, so exhausting this many attempts means the environment
45	// is being deployed to continuously rather than that the retry is broken.
46	const maxPushAttempts = 5
47	
48	// PublishOptions configures Publish.
49	type PublishOptions struct {
50		Repository *gitops.Repository
51		Plan       *Plan
52	
53		// CliVersion is recorded in a trailer so a bad deploy can be traced to the
54		// version that produced it.
55		CliVersion string
56	
57		// MaxAttempts defaults to maxPushAttempts.
58		MaxAttempts int
59	
60		// Backoff returns how long to wait before the given attempt (1-based).
61		// Defaults to jittered exponential.
62		Backoff func(attempt int) time.Duration
63	
64		// Sleep defaults to time.Sleep; tests replace it to avoid real delays.
65		Sleep func(time.Duration)
66	
67		Stderr io.Writer
68	}
69	
70	func (o *PublishOptions) applyDefaults() {
71		if o.MaxAttempts <= 0 {
72			o.MaxAttempts = maxPushAttempts
73		}
74		if o.Backoff == nil {
75			o.Backoff = jitteredBackoff
76		}
77		if o.Sleep == nil {
78			o.Sleep = time.Sleep
79		}
80		if o.Stderr == nil {
81			o.Stderr = io.Discard
82		}
83	}
84	
85	// Publish commits the overlay change and pushes it, rebasing and retrying if
86	// someone else pushed first.
87	//
88	// It returns the sha that actually landed on the remote. That is not necessarily
89	// the sha of the first commit: a rebase rewrites it, and every later step — the
90	// ArgoCD revision gate above all — must reason about the final one.
91	func Publish(ctx context.Context, opts PublishOptions) (string, error) {
92		opts.applyDefaults()
93	
94		repo := opts.Repository
95		plan := opts.Plan
96		rel := plan.RelKustomizationPath(repo.Root)
97	
98		// Stage only the file the plan changed. A blanket `git add -A` in a shared
99		// checkout would sweep up anything else that happened to be there.
100		if err := repo.Git.Add(ctx, rel); err != nil {
101			return "", err
102		}
103		if err := repo.Git.Commit(ctx, commitSubject(plan), commitTrailers(plan, opts.CliVersion)); err != nil {
104			return "", err
105		}
106	
107		refspec := "HEAD:" + repo.Branch
108		remoteRef := gitops.RemoteName + "/" + repo.Branch
109	
110		for attempt := 1; ; attempt++ {
111			err := repo.Git.Push(ctx, gitops.RemoteName, refspec)
112			if err == nil {
113				return repo.Git.HEAD(ctx)
114			}
115	
116			var rejected *git.PushRejectedError
117			if !errors.As(err, &rejected) {
118				// Authentication, network, a missing remote: retrying cannot help.
119				return "", err
120			}
121			if attempt >= opts.MaxAttempts {
122				return "", fmt.Errorf("gave up after %d push attempt%s: %s is being deployed to concurrently — try again",
123					opts.MaxAttempts, plural(opts.MaxAttempts), repo.Branch)
124			}
125	
126			fmt.Fprintf(opts.Stderr, "push rejected; rebasing onto %s and retrying (%d/%d)\n", remoteRef, attempt+1, opts.MaxAttempts)
127			opts.Sleep(opts.Backoff(attempt))
128	
129			if err := repo.Git.Fetch(ctx, gitops.RemoteName, repo.Branch); err != nil {
130				return "", err
131			}
132			if err := repo.Git.Rebase(ctx, remoteRef); err != nil {
133				var conflict *git.RebaseConflictError
134				if !errors.As(err, &conflict) {
135					return "", err
136				}
137				// A conflict here means someone deployed the *same component to the
138				// same environment* in the same moment, so both commits edit the
139				// same line. Auto-resolving would silently pick a winner and
140				// discard a deployment someone believes succeeded.
141				if abortErr := repo.Git.RebaseAbort(ctx); abortErr != nil {
142					return "", fmt.Errorf("%w (and the rebase could not be aborted: %v)", err, abortErr)
143				}
144				return "", fmt.Errorf("another deployment of %s to %s landed at the same moment, and the two changes conflict.\nNothing was pushed. Re-run to deploy on top of theirs",
145					plan.Coordinate, plan.Environment)
146			}
147		}
148	}
149	
150	// commitSubject is the one-line summary. The digest is abbreviated: a full one
151	// makes the subject unreadable in a log, and the trailer carries it in full.
152	//
153	// A release deploy names the version instead of the digest. A release is
154	// immutable, so the version identifies those digests exactly and is the more
155	// useful thing to read in a log; the trailers still carry every digest in full.
156	//
157	// The prefix is deploy() for a promotion too. A promotion makes the same edit to
158	// the same file, so calling it something else in the subject would split one
159	// history in two; TrailerPromotedFrom is what tells them apart.
160	func commitSubject(plan *Plan) string {
161		component, env, commit := plan.Coordinate.Component, plan.Environment, plan.Source.ShortCommit()
162	
163		if plan.ReleaseVersion != "" {
164			// Both versions known: the far more useful subject, and the only one that
165			// says what a promotion actually did.
166			if plan.PreviousRelease != "" && plan.PreviousRelease != plan.ReleaseVersion {
167				return fmt.Sprintf("deploy(%s): %s %s → %s", component, env, plan.PreviousRelease, plan.ReleaseVersion)
168			}
169			if len(plan.Pins) > 1 {
170				return fmt.Sprintf("deploy(%s): %s → %s, %d images (%s)", component, env, plan.ReleaseVersion, len(plan.Pins), commit)
171			}
172			return fmt.Sprintf("deploy(%s): %s → %s (%s)", component, env, plan.ReleaseVersion, commit)
173		}
174	
175		if len(plan.Pins) > 1 {
176			return fmt.Sprintf("deploy(%s): %s → %d images at %s", component, env, len(plan.Pins), commit)
177		}
178		return fmt.Sprintf("deploy(%s): %s → %s (%s)", component, env, shortDigest(plan.Pins[0].Digest), commit)
179	}
180	
181	func shortDigest(digest string) string {
182		const prefix = "sha256:"
183		if hex, ok := strings.CutPrefix(digest, prefix); ok && len(hex) > 12 {
184			return prefix + hex[:12]
185		}
186		return digest
187	}
188	
189	// commitTrailers builds the trailer block: one paragraph, one Key: value per
190	// line, which is what makes it machine-readable by `git log --format=%(trailers)`.
191	func commitTrailers(plan *Plan, cliVersion string) string {
192		trailers := []git.Trailer{
193			{Key: TrailerComponent, Value: plan.Coordinate.Component},
194			{Key: TrailerDomain, Value: plan.Coordinate.Domain},
195			{Key: TrailerSystem, Value: plan.Coordinate.System},
196			{Key: TrailerEnvironment, Value: plan.Environment},
197		}
198		// What was deployed where, before the per-image detail.
199		if plan.ReleaseVersion != "" {
200			trailers = append(trailers, git.Trailer{Key: TrailerRelease, Value: plan.ReleaseVersion})
201		}
202		if plan.PromotedFrom != "" {
203			trailers = append(trailers, git.Trailer{Key: TrailerPromotedFrom, Value: plan.PromotedFrom})
204		}
205		for _, pin := range plan.Pins {
206			trailers = append(trailers,
207				git.Trailer{Key: TrailerImage, Value: pin.Image},
208				git.Trailer{Key: TrailerDigest, Value: pin.Digest},
209			)
210		}
211		trailers = append(trailers, git.Trailer{Key: TrailerSourceCommit, Value: plan.Source.Commit})
212		if who := committer(); who != "" {
213			trailers = append(trailers, git.Trailer{Key: TrailerBy, Value: who})
214		}
215		if cliVersion != "" {
216			trailers = append(trailers, git.Trailer{Key: TrailerCli, Value: cliVersion})
217		}
218	
219		var b []byte
220		for i, t := range trailers {
221			if i > 0 {
222				b = append(b, '\n')
223			}
224			b = append(b, t.String()...)
225		}
226		return string(b)
227	}
228	
229	// committer identifies who ran the deploy, beyond git's own author fields: in
230	// CI the git identity is often a service account, so the environment is a
231	// better signal when it is set.
232	func committer() string {
233		for _, key := range []string{"GITLAB_USER_EMAIL", "GITHUB_ACTOR", "USER"} {
234			if v := os.Getenv(key); v != "" {
235				return v
236			}
237		}
238		return ""
239	}
240	
241	func plural(n int) string {
242		if n == 1 {
243			return ""
244		}
245		return "s"
246	}
247	
248	// jitteredBackoff grows the delay and spreads concurrent retries apart, so two
249	// deploys that collide do not keep colliding in lockstep.
250	func jitteredBackoff(attempt int) time.Duration {
251		base := 100 * time.Millisecond * (1 << min(attempt-1, 4))
252		return base + rand.N(base)
253	}
254

